from pathlib import Path

p = Path('LocalPfScanner.cs')
s = p.read_text(encoding='utf-8')


def replace_once(old: str, new: str, label: str):
    global s
    count = s.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly 1 match, found {count}')
    s = s.replace(old, new, 1)

replace_once(
    'using FFXIVClientStructs.FFXIV.Client.UI.Agent;\nusing FFXIVClientStructs.FFXIV.Component.GUI;',
    'using FFXIVClientStructs.FFXIV.Client.UI;\nusing FFXIVClientStructs.FFXIV.Client.UI.Agent;\nusing FFXIVClientStructs.FFXIV.Component.GUI;',
    'add AddonLookingForGroup using')

replace_once(
    '    private const int LocalPfMaxListingsPerPage = 50;\n    private const int SaturatedPageMissesBeforeRemoval = 3;',
    '    private const int LocalPfMaxListingsPerPage = 50;\n    private const int LocalPfMaximumPages = 10;\n    private const int SaturatedPageMissesBeforeRemoval = 3;',
    'add max pages')

